/* @lc app=leetcode id=2827 lang=kotlin */ class Solution { fun f(s: String, i: Int, diff: Int, rem: Int, tight: Boolean, st: Boolean, k: Int, m: HashMap<List<Any>, Int>): Int = if (i == s.length) (if (st && diff == 0 && rem == 0) 1 else 0) else m.getOrPut(listOf(i, diff, rem, tight, st)) { (0..(if (tight) s[i] - '0' else 9)).map { d -> if (!st && d == 0) f(s, i + 1, 0, 0, tight && d == s[i] - '0', false, k, m) else f(s, i + 1, diff + (if (d % 2 == 0) 1 else -1), (rem * 10 + d) % k, tight && d == s[i] - '0', true, k, m) }.sum() } fun numberOfBeautifulIntegers(low: Int, high: Int, k: Int): Int = f(high.toString(), 0, 0, 0, true, false, k, HashMap()) - f((low - 1).toString(), 0, 0, 0, true, false, k, HashMap()) }